var chatClient = app.Services.GetRequiredService<IChatClient>();
var researchTools = app.Services.GetRequiredService<ResearchTools>();
var noteTools = app.Services.GetRequiredService<NoteTools>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.WebSearch, "web_search",
        "Search the web for information on a query. Returns search result snippets."),
    AIFunctionFactory.Create(noteTools.TakeNote, "take_note",
        "Save a research note capturing a key finding or fact."),
};

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. When given a topic, use the web_search tool to find " +
    "information about it. Take notes on key findings using the take_note tool. " +
    "Perform multiple searches to get comprehensive coverage. " +
    "After researching, provide a final summary of your findings based on your notes.")
{
    Tools = tools,
};

Console.WriteLine("Research Agent Ready");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic thoroughly and summarize your findings: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Notes Collected ---");
foreach (var note in noteTools.GetNotes())
{
    Console.WriteLine($"• {note}");
}

/// <summary>Web search tool for the research agent.</summary>
public sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();

    [Description("The search query")]
    public async Task<string> WebSearch(string query, CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  [Searching: {query}]");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await s_httpClient.GetStringAsync(url, cancellationToken);

            if (string.IsNullOrWhiteSpace(response) || response.Length < 50)
            {
                return $"Search results for '{query}': No detailed results available. " +
                       "Try rephrasing the query or searching for more specific terms.";
            }

            return response.Length > 4000 ? response[..4000] : response;
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Note-taking tool for the research agent to record findings.</summary>
public sealed class NoteTools
{
    private readonly List<string> _notes = [];

    public string TakeNote([Description("The note content to save")] string content)
    {
        _notes.Add(content);
        Console.WriteLine($"  [Note saved: {content[..Math.Min(content.Length, 60)]}...]");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
}

